/** Delay to wait after the given number of failed attempts (1 = the first attempt failed). */
public Duration delayAfter(int failedAttempts) {
    if (failedAttempts < 1) {
        throw new IllegalArgumentException("failedAttempts must be >= 1");
    }
    Duration current = base;
    for (int i = 1; i < failedAttempts; i++) {
        Duration doubled;
        try {
            doubled = current.plus(current);
        } catch (ArithmeticException ex) {
            return max;
        }
        if (doubled.compareTo(max) >= 0) {
            return max;
        }
        // Guard against overflow wrapping to negative (should throw, but be safe)
        if (doubled.isNegative()) {
            return max;
        }
        current = doubled;
        if (current.compareTo(max) >= 0) {
            return max;
        }
    }
    if (current.compareTo(max) > 0) {
        return max;
    }
    return current;
}

